extension ARCHD {

  /*
   * routines that deal with file operations such as: creating, removing;
   * and setting access modes, uid/gid and times of files
   */

  //  #define FILEBITS		(S_ISVTX | S_IRWXU | S_IRWXG | S_IRWXO)
  //  #define SETBITS			(S_ISUID | S_ISGID)
