  /*
   * file_creat()
   *	Create and open a file.
   * Return:
   *	file descriptor or -1 for failure
   */

  func file_creat() -> FileDescriptor? {
    /*    int fd = -1;
     mode_t file_mode;
     int oerrno;

     int rc = 0;
     char *path_to_open;
     char *new_path;
     char *cwd;
     char cwd_buff[MAXPATHLEN];
     */

    /*
     * assume file doesn't exist, so just try to create it, most times this
     * works. We have to take special handling when the file does exist. To
     * detect this, we use O_EXCL. For example when trying to create a
     * file and a character device or fifo exists with the same name, we
     * can accidentally open the device by mistake (or block waiting to
     * open). If we find that the open has failed, then spend the effort
     * to figure out why. This strategy was found to have better average
     * performance in common use than checking the file (and the path)
     * first with lstat.
     */
    let file_mode = self.sb.permissions
    if ((fd = open(self.name, O_WRONLY | O_CREAT | O_TRUNC | O_EXCL,
                   file_mode)) >= 0) {
      return(fd);
    }

    /*
     * the file seems to exist. First we try to get rid of it (found to be
     * the second most common failure when traced). If this fails, only
     * then we go to the expense to check and create the path to the file
     */
    if (unlnk_exist(arcn.name, arcn.type) != 0) {
      return .failed;
    }

    path_to_open = arcn.name;
    new_path = arcn.name;
    cwd = getcwd(cwd_buff,sizeof(cwd_buff));
    if (cwd==NULL) { return -1; }

    for (;;) {
      /*
       * try to open it again, if this fails, check all the nodes in
       * the path and give it a final try. if chk_path() finds that
       * it cannot fix anything, we will skip the last attempt
       */

      if ((fd = open(path_to_open, O_WRONLY | O_CREAT | O_TRUNC,
                     file_mode)) >= 0) {
        /* clean up the invalid_action */
        if (pax_invalid_action>0) {
          record_pax_invalid_action_results(arcn, path_to_open);
        }
        break;
      }

      oerrno = errno;

      if (pax_invalid_action>0) {
        rc = perform_pax_invalid_action(arcn, oerrno);
        if (rc == 0) { continue; }
        if (rc == 1) {
          fd = -1;
          break;
        }
      }
      /* rc == 2 reserved for -o invalid_action=write */
      if (nodirs || chk_path(path_to_open,arcn.sb.userId,arcn.sb.groupId,
                             (rc==2) ? &new_path: NULL) < 0) {
        Tty.syswarn((pax_invalid_action==0), oerrno, "Unable to create %s", arcn.name);
        fd = -1;
        break;
      }

      if (new_path) { path_to_open = new_path; } /* try again */
    }
    if (new_path && strcmp(new_path, arcn.name)!=0) {
      dochdir(cwd);	/* go back to original directory */
    }

    return(fd);
  }

  /*
   * file_close()
   *	Close file descriptor to a file just created by pax. Sets modes,
   *	ownership and times as required.
   * Return:
   *	0 for success, -1 for failure
   */

  func file_close(_ arcn : ARCHD, _ fd : FileDescriptor?) {
    int res = 0;

    if (fd < 0) {
      return;
    }
    if (close(fd) < 0) {
      Tty.syswarn(false, errno, "Unable to close file descriptor on %s",
                  arcn.name);
    }

    /*
     * set owner/groups first as this may strip off mode bits we want
     * then set file permission modes. Then set file access and
     * modification times.
     */
    if (pids) {
      res = set_ids(arcn.name, arcn.sb.userId, arcn.sb.groupId);
    }

    else {
      res = 1; /* without pids, pax should NOT set s bits */
    }

    /*
     * IMPORTANT SECURITY NOTE:
     * if not preserving mode or we cannot set uid/gid, then PROHIBIT
     * set uid/gid bits
     */
    if !options.pmode || res {
      arcn.sb.st_mode &= ~(SETBITS);
    }
    if options.pmode {
      set_pmode(arcn.name, arcn.sb.st_mode);
    }
    if options.patime || options.pmtime {
      set_ftime(arcn.name, arcn.sb.lastModified, arcn.sb.st_atime, false, options)
    }
  }

  /*
   * lnk_creat()
   *	Create a hard link to arcn.ln_name from arcn.name. arcn.ln_name
   *	must exist;
   * Return:
   *	0 if ok, -1 otherwise
   */

  func lnk_creat() -> Result {
    /*
     * we may be running as root, so we have to be sure that link target
     * is not a directory, so we lstat and check
     */
    let sb : FileMetadata

    do {
      sb = try FileMetadata(for: FilePath(self.ln_name), followSymlinks: false)
    } catch(let e) {
      Tty.syswarn(true, e.code, "Unable to link to \(ln_name) from \(name)")
      return .failed
    }

    if sb.filetype == .directory {
      Tty.paxwarn(true, "A hard link to the directory \(ln_name) is not allowed")
      return .failed
    }

    if sb.filetype == .symbolicLink {
      int res;
      char buff[PATH_MAX+1];
      /*
       * Conformance: cannot make hard link to symlink - just make a
       * symlink to the target of the symlink
       */
      if ((res = readlink(arcn.ln_name, buff, sizeof(buff)-1)) < 0) {
        Tty.syswarn(true,errno,"Unable to symlink to %s from %s", arcn.ln_name,
                    arcn.name);
        return .failed;
      }
      buff[res] = 0;
      res = symlink(buff, arcn.name);
      return res;
    }

    return mk_link(ln_name, sb, name, false)
  }

  /*
   * cross_lnk()
   *	Create a hard link to arcn.org_name from arcn.name. Only used in copy
   *	with the -l flag. No warning or error if this does not succeed (we will
   *	then just create the file)
   * Return:
   *	1 if copy() should try to create this file node
   *	0 if cross_lnk() ok, -1 for fatal flaw (like linking to self).
   */

  func cross_lnk(_ arcn : ARCHD) -> Result {
    /*
     * try to make a link to original file (-l flag in copy mode). make sure
     * we do not try to link to directories in case we are running as root
     * (and it might succeed).
     */
    if (arcn.type == .DIR) {
      return .partial
    }

    if (arcn.type == PAX_SLK) {	/* for Unix 03 conformance tests 202,203 */
      if (!Lflag) {
        return .partial
      }
    }

    return(mk_link(arcn.org_name, &(arcn.sb), arcn.name, 1));
  }

  /*
   * chk_same()
   *	In copy mode if we are not trying to make hard links between the src
   *	and destinations, make sure we are not going to overwrite ourselves by
   *	accident. This slows things down a little, but we have to protect all
   *	those people who make typing errors.
   * Return:
   *	1 the target does not exist, go ahead and copy
   *	0 skip it file exists (-k) or may be the same as source file
   */

  func chk_same(_ arcn : ARCHD) -> Result {
    struct stat sb;

    /*
     * if file does not exist, return. if file exists and -k, skip it
     * quietly
     */
    if (lstat(arcn.name, &sb) < 0) {
      return .partial
    }
    if (kflag) {
      return .ok
    }

    /*
     * better make sure the user does not have src == dest by mistake
     */
    if ((arcn.sb.device == sb.device) && (arcn.sb.inode == sb.inode)) {
      Tty.paxwarn(true, "Unable to copy %s, file would overwrite itself",
                  arcn.name);
      return .ok
    }
    return .partial
  }

  /*
   * mk_link()
   *	try to make a hard link between two files. if ign set, we do not
   *	complain.
   * Return:
   *	0 if successful (or we are done with this file but no error, such as
   *	finding the from file exists and the user has set -k).
   *	1 when ign was set to indicates we could not make the link but we
   *	should try to copy/extract the file as that might work (and is an
   *	allowed option). -1 an error occurred.
   */

  private func mk_link(_ to : String, _ to_sb : FileMetadata, _ from : String, _ ign : Bool) -> Result {
    /*
     * if from file exists, it has to be unlinked to make the link. If the
     * file exists and -k is set, skip it quietly
     */

    if let sb = try? FileMetadata(for: FilePath(from) ) {
      if options.kflag {
        return .ok
      }

      /*
       * make sure it is not the same file, protect the user
       */

      if to_sb.device==sb.device && to_sb.inode == sb.inode {
        Tty.paxwarn(true, "Unable to link file \(to) to itself")
        return .failed
      }

      /*
       * try to get rid of the file, based on the type
       */
      if sb.filetype == .directory {
        if (rmdir(from) < 0) {
          Tty.syswarn(true, errno, "Unable to remove \(from)")
          return .failed
        }
      } else if (unlink(from) < 0) {
        if (!ign) {
          Tty.syswarn(true, errno, "Unable to remove \(from)")
          return .failed
        }
        return .partial
      }
    }

    /*
     * from file is gone (or did not exist), try to make the hard link.
     * if it fails, check the path and try it again (if chk_path() says to
     * try again)
     */
    while true {
      if (link(to, from) == 0) {
        break;
      }
      oerrno = errno;

      if (!nodirs && chk_path(from, to_sb.userId, to_sb.groupId, NULL) == 0) {

        continue;
      }
      if (!ign) {
        Tty.syswarn(true, oerrno, "Could not link to %s from %s", to,
                    from);
        return .failed;
      }
      return .partial
    }

    /*
     * all right the link was made
     */
    return .ok
  }

  /*
   * node_creat()
   *	create an entry in the file system (other than a file or hard link).
   *	If successful, sets uid/gid modes and times as required.
   * Return:
   *	0 if ok, -1 otherwise
   */

  func node_creat(_ options : pax.CommandOptions) -> Result {
    /*    int res;
     int ign = 0;
     int oerrno;
     int pass = 0;
     mode_t file_mode;
     struct stat sb;
     */

    /*
     * create node based on type, if that fails try to unlink the node and
     * try again. finally check the path and try again. As noted in the
     * file and link creation routines, this method seems to exhibit the
     * best performance in general use workloads.
     */
    let file_mode = self.sb.permissions
    var ign = false

    while true {
      switch self.type {
        case .DIR:
          res = mkdir(arcn.name, file_mode);
          if ign {
            res = 0
          }

        case .CHR:
          file_mode |= S_IFCHR;
          res = mknod(arcn.name, file_mode, arcn.sb.rawDevice);

        case .BLK:
          file_mode |= S_IFBLK;
          res = mknod(arcn.name, file_mode, arcn.sb.rawDevice);

        case .FIF:
          res = mkfifo(arcn.name, file_mode);

        case .SCK:
          /*
           * Skip sockets, operation has no meaning under BSD
           */
          Tty.paxwarn(false, "\(self.name) skipped. Sockets cannot be copied or extracted")
          return .failed
        case .SLK:
          res = symlink(arcn.ln_name, arcn.name);

        case .CTG, .HLK, .HRG, .REG:
          fallthrough
        default:
          /*
           * we should never get here
           */
          Tty.paxwarn(false, "\(self.name) has an unknown file type, skipping")
          return .failed
      }

      /*
       * if we were able to create the node break out of the loop,
       * otherwise try to unlink the node and try again. if that
       * fails check the full path and try a final time.
       */
      if (res == 0) {
        break;
      }

      /*
       * we failed to make the node
       */
      oerrno = errno;
      if ((ign = unlnk_exist(arcn.name, arcn.type)) < 0) {
        return .failed;
      }

      if (++pass <= 1) {
        continue;
      }


      if (nodirs || chk_path(arcn.name,arcn.sb.userId,arcn.sb.groupId, NULL) < 0) {

        Tty.syswarn(true, oerrno, "Could not create: \(self.name)")
        return .failed
      }
    }

    /*
     * we were able to create the node. set uid/gid, modes and times
     */
    if pids {
      res = set_ids(arcn.name, arcn.sb.userId, arcn.sb.groupId);
    }
    else {

      res = 1;	/* without pids, pax should NOT set s bits */
    }

    /*
     * symlinks are done now.
     */
    if self.type == .SLK {
      return .ok
    }

    /*
     * IMPORTANT SECURITY NOTE:
     * if not preserving mode or we cannot set uid/gid, then PROHIBIT any
     * set uid/gid bits
     */
    if !options.pmode || res {
      arcn.sb.st_mode &= ~(SETBITS);
    }
    if options.pmode {
      set_pmode(arcn.name, arcn.sb.st_mode);
    }

    if sekf.type == .DIR && NM_CPIO == programName {
      /*
       * Dirs must be processed again at end of extract to set times
       * and modes to agree with those stored in the archive. However
       * to allow extract to continue, we may have to also set owner
       * rights. This allows nodes in the archive that are children
       * of this directory to be extracted without failure. Both time
       * and modes will be fixed after the entire archive is read and
       * before pax exits.
       */
      if (access(arcn.name, R_OK | W_OK | X_OK) < 0) {
        if (lstat(arcn.name, &sb) < 0) {
          Tty.syswarn(false, errno,"Could not access %s (stat)",
                      arcn.name);
          set_pmode(arcn.name,file_mode | S_IRWXU);
        } else {
          /*
           * We have to add rights to the dir, so we make
           * sure to restore the mode. The mode must be
           * restored AS CREATED and not as stored if
           * pmode is not set.
           */
          set_pmode(arcn.name,
                    ((sb.st_mode & FILEBITS) | S_IRWXU));
          if !options.pmode {
            arcn.sb.st_mode = sb.st_mode;
          }
        }

        /*
         * we have to force the mode to what was set here,
         * since we changed it from the default as created.
         */
        add_dir(arcn.name, arcn.nlen, &(arcn.sb), 1);
      } else if options.pmode || options.patime || options.pmtime {
        add_dir(arcn.name, arcn.nlen, &(arcn.sb), 0);
      }
    }

    if options.patime || options.pmtime {

      set_ftime(arcn.name, arcn.sb.lastModified, arcn.sb.lastAccessed, false)
    }

    return .ok
  }

